protected void rebateDateTransactionTotalAmountCalculated(TAMRebateDateTrans _rebateDateTrans, Amount _amount)
{
    next rebateDateTransactionTotalAmountCalculated(_rebateDateTrans, _amount);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance())
            && _amount > 0
            && this.createDocument.getRebateTransactionType() == TAMRebateTransactionType::Rebate
            && this.createDocument.getRebatePosting().RebatePaymentType == TAMRebatePaymentType::Fund
        )
    {
        this.createFundOutput(_rebateDateTrans, _amount);
    }
}

private void createFundOutput(TAMRebateDateTrans _rebateDateTrans, Amount _amount)
{
    ttsbegin;

    CustAccount fundRecipient = this.rebateDeal.Recipient;

    if (!fundRecipient)
    {
        fundRecipient = LedgerDimensionFacade::getDisplayValueForLedgerDimension(this.createDocument.getRebatePosting().RebateLedgerDimension);
    }

    if (!fundRecipient)
    {
        throw error("@GlobalUnifiedPricing:FundRecipientEmpty");
    }

    CustTable recipientCustTable = CustTable::find(fundRecipient);
    if (recipientCustTable.InvoiceAccount)
    {
        fundRecipient = recipientCustTable.InvoiceAccount;
    }

    TAMFundTable tamFundTable;
    tamFundTable.FundID         = NumberSeq::newGetNum(TAMPromotionParameters::numRefFundID()).num();
    tamFundTable.TotalFundAmt   = _amount;
    tamFundTable.RebateRelated  = NoYes::Yes;
    tamFundTable.FundSourceType = GUPFundSourceType::Promotion;
    tamFundTable.FundValueType  = GUPFundValueType::Amount;
    tamFundTable.CurrencyCode   = this.rebateDeal.RebateCurrencyCode;

    // Skip total fund amount calculations.
    tamFundTable.doInsert();

    this.createFundCustCategory(tamFundTable, fundRecipient, _amount);

    _rebateDateTrans.FundID = TAMFundTable.FundID;
    _rebateDateTrans.RemittanceAccount = fundRecipient;
    _rebateDateTrans.update();

    ttscommit;
}

protected void createFundCustCategory(TAMFundTable _tamFundTable, CustAccount _fundRecipient, Amount _budgetAmount)
{
    TAMFundCustCategory tamFundCustCategoryParent;
    tamFundCustCategoryParent.Name           = _tamFundTable.FundID;
    tamFundCustCategoryParent.FundID         = _tamFundTable.FundID;
    tamFundCustCategoryParent.IsActive       = NoYes::Yes;
    tamFundCustCategoryParent.BudgetedAmount = _budgetAmount;
    tamFundCustCategoryParent.Level          = 1;
    tamFundCustCategoryParent.NestedSetLeft  = 1;
    tamFundCustCategoryParent.NestedSetRight = 4;
    tamFundCustCategoryParent.doInsert();

    TAMFundCustCategory tamFundCustCategoryChild;
    tamFundCustCategoryChild.Name           = _tamFundTable.FundID + '-' + _fundRecipient;
    tamFundCustCategoryChild.Customer       = CustTable::find(_fundRecipient).RecId;
    tamFundCustCategoryChild.ParentCategory = tamFundCustCategoryParent.RecId;
    tamFundCustCategoryChild.BudgetedAmount = _budgetAmount;
    tamFundCustCategoryChild.FundID         = _tamFundTable.FundID;
    tamFundCustCategoryChild.IsActive       = NoYes::Yes;
    tamFundCustCategoryChild.Level          = 2;
    tamFundCustCategoryChild.NestedSetLeft  = 2;
    tamFundCustCategoryChild.NestedSetRight = 3;
    tamFundCustCategoryChild.doInsert();
}
